#include <vector>

using namespace std;

class Solution {
public:
    int findPoisonedDuration(vector<int>& timeSeries, int duration) {
        int total = 0;
        for (int i = 0; i < timeSeries.size(); ++i) {
            if (i == 0) total += duration;
            else total += min(duration, timeSeries[i] - timeSeries[i - 1]);
        }
        return total;
    }
};
